-- Fingeravtryck efter körning, identiska med modellen (scripts/fingerprint-rules.ts cs1):
--   regler  60   md5 492330cc9630c0ed924a7425a996f28f   villkor 4520f2e2c23f64a42fd589f9f2a45647
--   värden  63   md5 69bf7c9c9e614fab2175250b1c9865c2
--   schema       md5 8322f38813e285324f64437ee615beac
-- Verifierat live: /sv/configurator/cs1 bygger CDS1L160-300-M9BW (nyckelns exempel,
-- sida 625), stoppar magnetcylindern för ø250 och varnar för tryckkärlslagen
-- (ø250 över 813 mm utan -V) samt bygger CS1B250-900-V.
--
-- CS1: beställnyckeln enligt SMC Air Cylinder CS1 Series.
-- GENERERAD ur src/lib/catalog/cs1.ts -- redigera inte för hand.
--
-- Rättar familjen cs1, som hade mallen 'CS1-{bore_mm}-{stroke_mm}-{cushioning}{sensing}'.
-- SMC:s kod är C{magnet}S1{fäste}{rör}{typ}{ø}{gänga}-{slag}{tillägg}-{givare}{kabel}{antal}-{special}-{tryckkärl},
-- t.ex. CDS1L160-300-M9BW (sida 625) och CS1L160-500 (sida 622). Fäste,
-- rörmaterial, typ, portgänga, tillägg och tryckkärlssymbolen fanns inte alls.
--
-- SMC-CS1 får katalogens borrningar, slag, temperatur och tryck.

begin;

create schema if not exists backup;
create table if not exists backup.cs1_before_20260915 as
  select 'param' as sort, p.id::text as id, p.param_key as k, p.label as v
  from configurator_params p join configurator_families f on f.id = p.family_id
  where f.slug = 'cs1'
  union all
  select 'value', v.id::text, v.code, v.label
  from configurator_param_values v
  join configurator_params p on p.id = v.param_id
  join configurator_families f on f.id = p.family_id
  where f.slug = 'cs1'
  union all
  select 'family', f.id::text, f.slug, coalesce(f.order_code_template, '')
  from configurator_families f where f.slug = 'cs1';

insert into config_schemas (schema_id, schema_json, title_sv, title_en, category_slug)
values ('SCHEMA-CS1-V1', '{"version":"1.0","steps":[{"id":"bore","step":1,"title_sv":"Kolvdiameter","title_en":"Bore size","required":true,"type":"single_select","options":[{"v":"125","label":"ø125 mm"},{"v":"140","label":"ø140 mm"},{"v":"160","label":"ø160 mm"},{"v":"180","label":"ø180 mm"},{"v":"200","label":"ø200 mm"},{"v":"250","label":"ø250 mm"},{"v":"300","label":"ø300 mm"}]},{"id":"mounting","step":2,"title_sv":"Fäste","title_en":"Mounting","required":true,"type":"single_select","options":[{"v":"B","label":"Basutförande"},{"v":"L","label":"Fotfäste"},{"v":"F","label":"Fläns vid kolvstången"},{"v":"G","label":"Fläns vid gaveln"},{"v":"C","label":"Enkelt gaffelfäste"},{"v":"D","label":"Dubbelt gaffelfäste (med sprint och saxpinne)"},{"v":"T","label":"Centrerat tappfäste"}]},{"id":"stroke_mm","step":3,"title_sv":"Slaglängd","title_en":"Cylinder stroke","required":true,"type":"numeric","min":1,"max":2400,"unit":"mm"},{"id":"magnet","step":4,"title_sv":"Inbyggd magnet","title_en":"Built-in magnet","required":false,"type":"single_select","options":[{"v":"D","label":"Inbyggd magnet för givare (CDS1, ø125–200)"}]},{"id":"tubing","step":5,"title_sv":"Rörmaterial","title_en":"Tubing material","required":false,"type":"single_select","options":[{"v":"F","label":"Stålrör där aluminiumrör är standard (ø125/140 ≤ 1000, ø160 ≤ 1200; ej magnetcylinder)"}]},{"id":"type","step":6,"title_sv":"Typ (standard är smord)","title_en":"Type (lube is standard)","required":false,"type":"single_select","options":[{"v":"N","label":"Osmord (non-lube)"},{"v":"H","label":"Lufthydraulisk, turbinolja (ø125–160, utan dämpning)"}]},{"id":"port","step":7,"title_sv":"Portgänga","title_en":"Port thread type","required":false,"type":"single_select","options":[{"v":"TN","label":"Portgänga NPT (standard är Rc)"},{"v":"TF","label":"Portgänga G (standard är Rc)"}]},{"id":"suffix","step":8,"title_sv":"Tillägg: bälg och dämpning (standard är dämpning i båda ändar)","title_en":"Suffix: rod boot and cushion (cushion both ends is standard)","required":false,"type":"single_select","options":[{"v":"N","label":"Utan dämpning"},{"v":"R","label":"Dämpning bara vid kolvstången"},{"v":"H","label":"Dämpning bara vid gaveln"},{"v":"J","label":"Bälg i nylonduk (max 70 °C)"},{"v":"K","label":"Värmebeständig bälg (max 110 °C)"},{"v":"JN","label":"Bälg i nylonduk, utan dämpning"},{"v":"JR","label":"Bälg i nylonduk, dämpning bara vid kolvstången"},{"v":"HJ","label":"Bälg i nylonduk, dämpning bara vid gaveln"},{"v":"KN","label":"Värmebeständig bälg, utan dämpning"},{"v":"KR","label":"Värmebeständig bälg, dämpning bara vid kolvstången"},{"v":"HK","label":"Värmebeständig bälg, dämpning bara vid gaveln"}]},{"id":"switch","step":9,"title_sv":"Magnetgivare","title_en":"Auto switch","required":false,"type":"single_select","options":[{"v":"M9N","label":"D-M9N, 3-tråd NPN"},{"v":"M9P","label":"D-M9P, 3-tråd PNP"},{"v":"M9B","label":"D-M9B, 2-tråd"},{"v":"M9NW","label":"D-M9NW, NPN, tvåfärgsindikering"},{"v":"M9PW","label":"D-M9PW, PNP, tvåfärgsindikering"},{"v":"M9BW","label":"D-M9BW, 2-tråd, tvåfärgsindikering"},{"v":"M9NA","label":"D-M9NA, NPN, vattentät"},{"v":"M9PA","label":"D-M9PA, PNP, vattentät"},{"v":"M9BA","label":"D-M9BA, 2-tråd, vattentät"},{"v":"A96","label":"D-A96, reed 3-tråd"},{"v":"A93","label":"D-A93, reed 2-tråd"},{"v":"A90","label":"D-A90, reed utan indikering"}]},{"id":"lead","step":10,"title_sv":"Givarens kabellängd","title_en":"Lead wire length","required":false,"type":"single_select","options":[{"v":"M","label":"1 m kabel"},{"v":"L","label":"3 m kabel"},{"v":"Z","label":"5 m kabel"}]},{"id":"count","step":11,"title_sv":"Antal givare","title_en":"Number of auto switches","required":false,"type":"single_select","options":[{"v":"S","label":"En givare (standard är två)"},{"v":"3","label":"Tre givare"}]},{"id":"mto","step":12,"title_sv":"Specialutförande","title_en":"Made to order","required":false,"type":"single_select","options":[{"v":"XA","label":"-XA□ Ändrad kolvstångsände (mått anges vid beställning)"},{"v":"XB5","label":"-XB5 Grov kolvstång (ø125–200)"},{"v":"XB6","label":"-XB6 Värmebeständig –10…150 °C (bara osmord, ø125–200)"},{"v":"XC3","label":"-XC3 Speciell portplacering"},{"v":"XC4","label":"-XC4 Kraftig avstrykare"},{"v":"XC5","label":"-XC5 Värmebeständig –10…110 °C (ej lufthydraul)"},{"v":"XC6","label":"-XC6 Rostfritt utförande"},{"v":"XC22","label":"-XC22 Fluorgummitätningar"},{"v":"XC26","label":"-XC26 Gaffelsprintar med planbricka"},{"v":"XC27","label":"-XC27 Rostfria gaffelsprintar (SS304)"},{"v":"XC30","label":"-XC30 Tappfäste vid kolvstången, monterat på gavelns front"},{"v":"XC35","label":"-XC35 Spiralavstrykare"},{"v":"XC68","label":"-XC68 Hårdkromad rostfri kolvstång"},{"v":"XC86","label":"-XC86 Med kolvstångsände (rod end bracket)"}]},{"id":"vessel","step":13,"title_sv":"Tryckkärlslagen (Japan)","title_en":"Pressure Vessel Act (Japan)","required":false,"type":"single_select","options":[{"v":"V","label":"Används inte i Japan — undantag från tryckkärlslagen klass 2 (bara slag som omfattas; ej magnetcylinder)"}]}]}'::jsonb,
        'SMC CS1 dragstångscylinder ø125–300', 'SMC CS1 large-bore tie-rod cylinder', 'cylinder')
on conflict (schema_id) do update set
  schema_json = excluded.schema_json,
  title_sv = excluded.title_sv,
  title_en = excluded.title_en;

update configurator_families set
  title = 'Dragstångscylinder ø125–300, dubbelverkande enkel kolvstång',
  description = 'SMC CS1 large-bore tie-rod cylinder, double acting single rod, ø125–300 mm, lube/non-lube/air-hydro, aluminium or steel tube, strokes up to 2400 mm.',
  stroke_min_mm = 1,
  stroke_max_mm = 2400,
  order_code_template = 'C{magnet}S1{mounting}{tubing}{type}{bore}{port}-{stroke_mm}{suffix}-{switch}{lead}{count}-{mto}-{vessel}',
  rules_schema_id = 'SCHEMA-CS1-V1'
where slug = 'cs1';


